// Deterministic fan-in and state formatting
const result = $input.first().json || {};
const src = $("02 - Parse & Validate Message").first().json;
const profile = ($("03 - Profile Agent").first().json || {}).output || {};
const supervisor = ($("04 - Supervisor Agent").first().json || {}).output || {};
const action = supervisor.action || "TEACH";
const topic = supervisor.topic || src.topic || "Probability";

let response;
if (typeof result.output === "string") response = result.output;
else if (result.response) response = result.response;
else if (result.correct !== undefined) response = "Answer recorded: " + (result.correct ? "correct" : "incorrect") + " for " + result.topic + ".";
else if (result.new_mastery !== undefined) response = topic + " mastery: " + result.old_mastery + "% -> " + result.new_mastery + "%";
else if (result.diagnostic) response = "Diagnostic assessment ready.";
else if (result.question) response = result.question;
else response = "Processed action: " + action + ".";

return [{ json: {
  ok: true,
  action,
  topic,
  response,
  agent_output: result,
  student_state: {
    student_id: src.student_id,
    goal: profile.goal || null,
    days_remaining: profile.days_remaining || null,
    daily_study_minutes: profile.daily_study_minutes || null,
    last_action: action,
    last_topic: topic,
    last_mastery: result.new_mastery !== undefined ? result.new_mastery : (src.mastery || 40)
  }
} }];
